ick integer, population_growth numeric DEFAULT 0, "GDP_growth" bigint DEFAULT 0, debt_growth numeric DEFAULT 0, unemployment numeric DEFAULT 50, labor_force_participation numeric DEFAULT 50, minimum_wage numeric DEFAULT 50, union_strength numeric DEFAULT 50, immigration numeric DEFAULT 50, illegal_immigration numeric DEFAULT 50, emigration numeric DEFAULT 50, corporate_tax numeric DEFAULT 50, sales_tax numeric DEFAULT 50, interest_rates numeric DEFAULT 50, poverty_rate numeric DEFAULT 50, income_inequality numeric DEFAULT 50, trade_balance numeric DEFAULT 50, currency_strength numeric DEFAULT 50, birth_rate numeric DEFAULT 50, death_rate numeric DEFAULT 50, median_age integer DEFAULT 38, carbon_emissions numeric DEFAULT 50, renewable_energy_percentage numeric DEFAULT 20, corruption numeric DEFAULT 50, press_freedom numeric DEFAULT 50, judicial_independence numeric DEFAULT 50, incarceration_rate numeric DEFAULT 50, drug_use numeric DEFAULT 50, ethnic_diversity numeric DEFAULT 50, international_reputation numeric DEFAULT 50, trade_agreements numeric DEFAULT 0, sanctions numeric DEFAULT 0, gdp_growth numeric DEFAULT 50, individualism_voters integer DEFAULT 50, liberty_voters integer DEFAULT 50, security_voters integer DEFAULT 50, globalism_voters integer DEFAULT 50, head_of_state_first_name text, head_of_state_last_name text, first_name_pool text[], last_name_pool text[], flag_url text, head_of_state_age integer, gdp numeric DEFAULT 50, equality_voters integer DEFAULT 0, freedom_voters integer DEFAULT 0, tradition_voters integer DEFAULT 0, progress_voters integer DEFAULT 0, nationalism_voters integer DEFAULT 0, cooperation_voters integer DEFAULT 0, education_accessibility numeric DEFAULT 50, healthcare_accessibility numeric DEFAULT 50, ruling_faction_id uuid, seed_stats jsonb, revolution_started_tick integer, revolution_duration integer, physical_infrastructure numeric DEFAULT 50, last_budget_tick integer, last_budget_bill_id uuid, budget_reserves numeric DEFAULT 0, national_approval numeric DEFAULT 50, gov_approval real DEFAULT 50, gov_approval_institutional real DEFAULT 50, gov_approval_outcomes real DEFAULT 50, gov_approval_events real DEFAULT 0, failed_formation_attempts integer DEFAULT 0, last_default_tick integer, debt_service_burden numeric DEFAULT 0, credit_locked_out boolean DEFAULT false, successor_cooldown_end_tick integer, impeachment_cooldown_until_tick integer, regime_health numeric NOT NULL DEFAULT 80, unaligned_seats integer NOT NULL DEFAULT 0, last_redistribute_tick integer);

CREATE TABLE IF NOT EXISTS nations_history (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid, tick integer NOT NULL, recorded_at timestamp with time zone DEFAULT now(), population numeric, gdp numeric, debt numeric, gdp_growth numeric, debt_growth numeric, population_growth numeric, budget numeric, inflation numeric, interest_rates numeric, trade_balance numeric, currency_strength numeric, foreign_investment numeric, credit numeric, income_tax numeric, corporate_tax numeric, sales_tax numeric, tariffs numeric, unemployment numeric, labor_force_participation numeric, minimum_wage numeric, union_strength numeric, poverty_rate numeric, income_inequality numeric, birth_rate numeric, death_rate numeric, median_age numeric, eligible_voters numeric, ethnic_diversity numeric, healthcare_quality numeric, beds_per_100k numeric, lifespan numeric, drug_use numeric, literacy numeric, higher_education numeric, academic_immigration numeric, digital_infrastructure numeric, rail_network numeric, urbanization numeric, energy_generation numeric, renewable_energy_percentage numeric, arable_land numeric, rare_minerals numeric, oil_and_gas numeric, fuel_prices numeric, pollution numeric, carbon_emissions numeric, standard_of_living numeric, happiness numeric, social_mobility numeric, benefits numeric, crime_rate numeric, incarceration_rate numeric, stability numeric, legitimacy numeric, efficiency numeric, corruption numeric, press_freedom numeric, judicial_independence numeric, freedom_index numeric, polarization numeric, civil_unrest numeric, terrorism numeric, political_violence numeric, immigration numeric, illegal_immigration numeric, emigration numeric, international_reputation numeric, trade_agreements numeric, sanctions numeric, competition_voters numeric, liberty_voters numeric, security_voters numeric, globalism_voters numeric, healthcare_accessibility numeric, education_accessibility numeric, religious numeric, progressive_voters numeric, liberal_voters numeric, moderate_voters numeric, conservative_voters numeric, nationalist_voters numeric, physical_infrastructure numeric, gov_approval numeric);

CREATE TABLE IF NOT EXISTS npc_party_actions (id uuid NOT NULL DEFAULT gen_random_uuid(), npc_party_id uuid NOT NULL, nation_id uuid NOT NULL, action_type text NOT NULL, tick_performed integer NOT NULL, action_data jsonb, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS npc_party_names (id uuid NOT NULL DEFAULT gen_random_uuid(), party_name text NOT NULL, abbreviation text NOT NULL, ideology_value_1 text, ideology_value_2 text, used boolean DEFAULT false, nation_id uuid);

CREATE TABLE IF NOT EXISTS op_eds (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, faction_id uuid NOT NULL, headline text NOT NULL, body text NOT NULL, topic text NOT NULL DEFAULT 'domestic'::text, publish_tick integer NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), author_faction_id uuid, author_name text NOT NULL DEFAULT ''::text, section text NOT NULL DEFAULT 'opinion'::text, topic_tags jsonb DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'draft'::text, published_tick integer, updated_at timestamp with time zone DEFAULT now(), is_front_page boolean DEFAULT false, reward_ap integer DEFAULT 0, reward_granted boolean DEFAULT false, is_official_dispatch boolean DEFAULT false);

CREATE TABLE IF NOT EXISTS pander_history (id uuid NOT NULL DEFAULT gen_random_uuid(), faction_id uuid NOT NULL, nation_id uuid NOT NULL, bloc_key character varying(50) NOT NULL, mode character varying(20) NOT NULL, tick integer NOT NULL, multiplier numeric(3,2) NOT NULL DEFAULT 1.0, empty_pandering_applied boolean NOT NULL DEFAULT false, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS parties (id uuid NOT NULL DEFAULT gen_random_uuid(), shard_id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL DEFAULT gen_random_uuid(), party_name text NOT NULL, abbreviation text NOT NULL, ideology_value_1 text NOT NULL, ideology_value_2 text NOT NULL, seats text DEFAULT '0'::text, overall_approval text DEFAULT '50'::text, player_id uuid, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS party_interest_approvals (id uuid NOT NULL DEFAULT gen_random_uuid(), party_id uuid NOT NULL DEFAULT gen_random_uuid(), interest_group_id uuid NOT NULL DEFAULT gen_random_uuid(), approval_rating integer NOT NULL DEFAULT 50, updataed_at timestamp with time zone NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS pending_actions (id uuid NOT NULL DEFAULT gen_random_uuid(), faction_id uuid, action_type text, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS player_articles (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, author_faction_id uuid, author_name text NOT NULL, headline text NOT NULL, body text NOT NULL, category text NOT NULL DEFAULT 'politics'::text, image_url text, status text NOT NULL DEFAULT 'draft'::text, published_tick integer, reward_ap integer DEFAULT 0, reward_granted boolean DEFAULT false, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS player_bans (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, fingerprint text, reason text DEFAULT 'Multi-accounting'::text, banned_at timestamp with time zone DEFAULT now(), banned_by text, expires_at timestamp with time zone, is_active boolean DEFAULT true);

CREATE TABLE IF NOT EXISTS player_fingerprints (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, fingerprint text NOT NULL, components jsonb DEFAULT '{}'::jsonb, ip_address text, user_agent text, first_seen_at timestamp with time zone DEFAULT now(), last_seen_at timestamp with time zone DEFAULT now(), visit_count integer DEFAULT 1);

CREATE TABLE IF NOT EXISTS pm_candidates (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid, faction_id uuid, first_name text NOT NULL, last_name text NOT NULL, age integer NOT NULL, ideology text NOT NULL, ideology_axis text NOT NULL, ideology_direction integer NOT NULL, trait_key text, created_at_tick integer NOT NULL, selected boolean DEFAULT false, created_at timestamp with time zone DEFAULT now(), candidate_type text DEFAULT 'pm'::text);

CREATE TABLE IF NOT EXISTS policies (id uuid NOT NULL DEFAULT gen_random_uuid(), policy_key text NOT NULL, policy_name text NOT NULL, description text NOT NULL, major_sector text NOT NULL, minor_sector text NOT NULL, ideology text NOT NULL, target_stat text NOT NULL, stat_direction text NOT NULL, stat_change integer DEFAULT 5, secondary_stat text, secondary_direction text, secondary_change integer, ap_cost integer DEFAULT 2, upfront_cost bigint DEFAULT 0, ongoing_cost bigint DEFAULT 0, is_active boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), cost_scaling_stat text, cost_scaling_stat_2 text, immediate_min integer DEFAULT 1, immediate_max integer DEFAULT 3, ongoing_tick_change numeric(3,1) DEFAULT 0.1, ongoing_max_total integer DEFAULT 10, conflict_group integer, stat_change_per_tick numeric DEFAULT 1, duration_months integer DEFAULT 12, stat_ceiling integer DEFAULT 100, stat_floor integer DEFAULT 0, cost_relief numeric DEFAULT 0, ongoing_cost_per_tick numeric DEFAULT 0, side_effects jsonb, approval_impact integer DEFAULT 0, ideologies jsonb, one_time_only boolean DEFAULT false, enacted_nation_ids jsonb DEFAULT '[]'::jsonb, law_category text, ongoing_base_cost numeric DEFAULT 0, ongoing_scaling_stat text, stat_effects jsonb, opposed_policy_ids uuid[], upfront_scaling_stat text, requires_policy_id uuid, policy_type text DEFAULT 'structural'::text, fiscal_category text);

CREATE TABLE IF NOT EXISTS presidents (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, faction_id uuid NOT NULL, first_name text NOT NULL, last_name text NOT NULL, age integer, ideology text, trait text, trait_upside text, trait_downside text, elected_tick integer NOT NULL, term_ends_tick integer NOT NULL, is_active boolean DEFAULT true, approval_modifier integer DEFAULT 0, created_at timestamp with time zone DEFAULT now(), terms_served integer DEFAULT 1, removal_reason text);

CREATE TABLE IF NOT EXISTS regime_pillars (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, pillar_key text NOT NULL, pillar_name text NOT NULL, support integer NOT NULL DEFAULT 70, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), steward_faction_id uuid);

CREATE TABLE IF NOT EXISTS shakeups (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, trigger_type text NOT NULL, initiated_by uuid, ruling_faction_id uuid, status text NOT NULL DEFAULT 'voting'::text, votes jsonb DEFAULT '[]'::jsonb, result jsonb, created_at timestamp with time zone DEFAULT now(), resolved_at timestamp with time zone, created_tick integer);

CREATE TABLE IF NOT EXISTS shard (id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, is_active boolean NOT NULL DEFAULT true, current_tick integer NOT NULL DEFAULT 0, next_tick_at timestamp with time zone, created_at timestamp with time zone NOT NULL DEFAULT now(), "current_date" text, tick_interval_hours integer DEFAULT 1, tick_processing boolean NOT NULL DEFAULT false, tick_processing_started_at timestamp with time zone);

CREATE TABLE IF NOT EXISTS stat_connections (id uuid NOT NULL DEFAULT gen_random_uuid(), source_stat text NOT NULL, source_dir text NOT NULL, threshold numeric NOT NULL, target_stat text NOT NULL, target_dir text NOT NULL, magnitude numeric NOT NULL DEFAULT 0.1, delay_ticks integer NOT NULL DEFAULT 0, dampening boolean NOT NULL DEFAULT true, category text NOT NULL DEFAULT 'economic'::text, enabled boolean NOT NULL DEFAULT true, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS stat_history (nation_id uuid NOT NULL, stat_name text NOT NULL, value real NOT NULL, tick integer NOT NULL);

CREATE TABLE IF NOT EXISTS stewards (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, faction_id uuid NOT NULL, pillar_key text NOT NULL, steward_type text NOT NULL, first_name text NOT NULL, last_name text NOT NULL, age integer NOT NULL, standing integer NOT NULL DEFAULT 40, power_base integer NOT NULL DEFAULT 30, true_loyalty integer NOT NULL DEFAULT 50, coup_readiness integer NOT NULL DEFAULT 0, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), estimated_loyalty integer NOT NULL DEFAULT 55, personal_wealth numeric NOT NULL DEFAULT 0, exit_readiness integer NOT NULL DEFAULT 0, is_alive boolean NOT NULL DEFAULT true, created_at_tick integer, died_at_tick integer, is_chosen_successor boolean NOT NULL DEFAULT false, succession_strength integer NOT NULL DEFAULT 0, successor_appointed_tick integer);

CREATE TABLE IF NOT EXISTS trade_agreements (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_a_id uuid NOT NULL, nation_b_id uuid NOT NULL, negotiation_id uuid, bill_a_id uuid, bill_b_id uuid, agreement_type text NOT NULL, agreement_name text NOT NULL, articles jsonb NOT NULL DEFAULT '[]'::jsonb, duration_type text NOT NULL DEFAULT 'fixed'::text, duration_ticks integer, auto_renew boolean DEFAULT false, withdrawal_notice_ticks integer DEFAULT 3, status text NOT NULL DEFAULT 'active'::text, enacted_at_tick integer NOT NULL, expires_at_tick integer, withdrawn_at_tick integer, withdrawal_notice_at integer, withdrawn_by_nation uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS trade_flows (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, tick integer NOT NULL, sector text NOT NULL, export_capacity numeric DEFAULT 0, export_volume numeric DEFAULT 0, import_demand numeric DEFAULT 0, import_volume numeric DEFAULT 0, net_flow numeric DEFAULT 0, price_modifier numeric DEFAULT 1.0, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS trade_negotiations (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_a_id uuid NOT NULL, nation_b_id uuid NOT NULL, initiating_proposal_id uuid, agreement_type text NOT NULL, status text NOT NULL DEFAULT 'open'::text, participants jsonb DEFAULT '[]'::jsonb, draft_articles jsonb DEFAULT '[]'::jsonb, agreement_name text, expires_at_tick integer NOT NULL, extension_requested_a boolean DEFAULT false, extension_requested_b boolean DEFAULT false, extensions_used integer DEFAULT 0, approved_by_a uuid, approved_by_a_role text, approved_at_a_tick integer, approved_by_b uuid, approved_by_b_role text, approved_at_b_tick integer, bill_a_id uuid, bill_b_id uuid, opened_at_tick integer NOT NULL, concluded_at_tick integer, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS trade_partners (id uuid NOT NULL DEFAULT gen_random_uuid(), tick integer NOT NULL, exporter_nation_id uuid NOT NULL, importer_nation_id uuid NOT NULL, sector text NOT NULL, trade_volume numeric DEFAULT 0, affinity_score numeric DEFAULT 0, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS trade_summary (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, tick integer NOT NULL, total_exports numeric DEFAULT 0, total_imports numeric DEFAULT 0, trade_surplus numeric DEFAULT 0, trade_balance_index numeric DEFAULT 50, tariff_revenue numeric DEFAULT 0, top_export_sector text, top_import_sector text, dependency_alerts jsonb DEFAULT '[]'::jsonb, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS valdorian_articles (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, event_type text NOT NULL, tier integer NOT NULL DEFAULT 3, section text NOT NULL DEFAULT 'politics'::text, headline text NOT NULL, subheadline text, lede text, body_paragraphs jsonb DEFAULT '[]'::jsonb, quotes jsonb DEFAULT '[]'::jsonb, byline_reporter text, topic_tags jsonb DEFAULT '[]'::jsonb, developing_story jsonb, source_event_id text, tick integer NOT NULL, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS voter_bloc_demands (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid, voter_bloc_id uuid, bloc_name text NOT NULL, target_stat text NOT NULL, desired_range text NOT NULL, current_value integer, created_at_tick integer NOT NULL, deadline_tick integer NOT NULL, demand_text text, consequence_text text, status text DEFAULT 'active'::text, resolved_at_tick integer, approval_penalty integer DEFAULT 5, created_at timestamp with time zone DEFAULT now());

CREATE TABLE IF NOT EXISTS voter_blocs (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid, bloc_name text NOT NULL, description text, voter_count integer NOT NULL DEFAULT 0, ideology_1 text, ideology_2 text, ideology_3 text, priority_stat text, stat_preference text, stat_preferences_full jsonb, is_active boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), ideology_4 text, ideology_5 text, population_weight numeric(5,2) DEFAULT 0, axis_liberty_equality integer DEFAULT 50, axis_tradition_progress integer DEFAULT 50, axis_security_freedom integer DEFAULT 50, axis_globalism_nationalism integer DEFAULT 50, axis_individualism_collectivism integer DEFAULT 50, priority_issues jsonb DEFAULT '[]'::jsonb, k_value numeric(4,1) DEFAULT 10);

CREATE TABLE IF NOT EXISTS wiki_pages (id uuid NOT NULL DEFAULT gen_random_uuid(), nation_id uuid NOT NULL, slug text NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT ''::text, template_type text, template_data jsonb DEFAULT '[]'::jsonb, infobox_image text, created_by uuid, updated_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), locked_by uuid);
